INSERT INTO measures (number, description, responsible, sectionId, orderIndex) VALUES
('16', 'Executar as eventuais propostas de minimização complementares definidas aquando da identificação dos valores patrimoniais até a presente fase.', 'EE | RAP', 2, 21),
('17', 'Implementar os estaleiros nos locais propostos no RECAPE e na pronúncia apresentada pelo proponente em sede de audiência prévia.', 'EE', 4, 22),
('18', 'As áreas dos estaleiros não devem ser impermeabilizadas, com exceção dos locais de manuseamento e armazenamento de substâncias poluentes. No caso dos produtos perigosos deve ser garantida a construção de uma bacia de retenção, impermeabilizada e isolada da rede de drenagem natural.', 'EE | RAA', 4, 23),
('19', 'Proceder à vedação das áreas de estaleiro, ou na sua impossibilidade, delimitação da área afeta ao mesmo com sinalização visível. Na vedação devem ser colocadas placas avisadoras que incluam as regras de segurança a observar, assim como a calendarização das obras.', 'EE | RAA', 4, 24),
('20', 'Recorrer a mão-de-obra local ou regional, sempre que possível, e promover as ações (preventivas} de formação necessárias ao adequado desempenho das funções requeridas.', 'DO | EE', 4, 25),
('21', 'Assegurar que a iluminação que possa ser usada no exterior, incluindo estaleiros, não é projetada de forma intrusiva sobre a envolvente e sobre as habitações próximas sempre que aplicável. Nesse sentido, a mesma deve ser o mais dirigida possível para baixo, segundo a vertical, e apenas sobre os locais que efetivamente a exigem.', 'EE', 4, 26),
('22', 'Realizar os trabalhos de desmatação e desarborização deverão ser realizados fora da época de reprodução da maioria das espécies: de março a final de junho.', 'DO | EE', 5, 27),
('23', 'Realizar as ações de corte de vegetação deverão ser realizadas de forma gradual e reduzidas ao mínimo indispensável à execução dos trabalhos de modo a reduzir o tempo de exposição do solo.', 'EE', 5, 28),
('24', 'Os trabalhos desarborização, desmatação e decapagem de solos deverão ser limitados às áreas estritamente necessárias à execução dos trabalhos, devendo proceder-se à balizagem prévia das áreas a intervencionar. Para o efeito:', 'EE', 5, 29),
('24.1', 'Previamente ao início das intervenções, o limite das áreas de implantação deve ser sinalizado. Enquanto não for aplicada a vedação perimetral definitiva, a delimitação pode ser feita provisoriamente, embora de forma clara.', 'EE', 5, 30),
('24.2', 'Estaleiro: o estaleiro deverá ser vedado em toda a sua extensão.', 'EE', 5, 31),
('24.3', 'Devem ser delimitados os locais provisórios de depósitos de terras.', 'EE', 5, 32),
('24.4', 'Devem ser delimitadas outras zonas de armazenamento de materiais e equipamentos, que pela sua dimensão não podem ser armazenados no estaleiro.', 'EE', 5, 33),
('24.5', 'Áreas a intervencionar para instalação dos apoios das Linhas elétricas, área de apoio à montagem e respetivos acessos.', 'EE', 5, 34),
('25', 'O corte dos sobreiros deve ser horizontal ou ligeiramente inclinado, executado rente ao solo e com superfície absolutamente lisa.', 'EE | RAA', 5, 35),
('26', 'Evitar o abate e afetação de sobreiros na implantação dos apoios e acessos, sempre que tecnicamente possível.', 'EE | RAA', 5, 36),
('27', 'Não podem ser efetuadas escavações não previstas na proximidade de sobreiros ou azinheiras, devendo ser respeitada uma distância de segurança correspondente ao dobro do raio da copa, no mínimo de 4 m de raio (árvores jovens), quer no que respeita aos acessos a criar ou a reabilitar, quer no que diz respeito à preparação da área de trabalho a criar junto de cada apoio. Se com esta limitação surgirem situações em que não seja possível criar acessos com condições para circulação de autobetoneiras, o betão terá de ser feito junto a cada apoio, e o transporte de material e matéria-prima necessária deve ser feito em trator.', 'EE | RAA', 5, 37),
('28', 'Caso a implementação da faixa de proteção da linha ou da faixa de gestão de combustível, implique o abate ou afetação de sobreiros ou azinheiras, esta ação deve ser comunicada ao ICNF e deve existir compensação, com os mesmos valores que se encontram definidos no Projeto de Compensação pelo abate e afetação de sobreiros.', 'DO | EE', 5, 38),
('29', 'No corredor da linha elétrica devem ser mantidas, sempre que possível, as unidades de vegetação natural e seminatural. Caso os exemplares arbóreos ponham em causa a segurança da linha, estes devem ser sujeitos a técnicas de poda, em detrimento do seu corte. Esta medida aplica-se sobretudo para indivíduos das espécies Quercus suber (sobreiro) e Quercus rotundifofia (azinheira).', 'EE | RAA', 5, 39),
('30', 'A terra viva/vegetal proveniente das operações de decapagem, possuidora do banco de sementes das espécies autóctones, deve ser removida e depositada em pargas. Estas devem ter até 3 m de altura; devem ser colocadas próximo das áreas de onde foram removidas, mas assegurando que tal se realiza em áreas planas e bem drenadas; e devem ser protegidas contra a erosão hídrica e eólica através de uma sementeira de leguminosas e/ou da sua cobertura, se necessário e aplicável, em função dos tempos de duração e das condições atmosféricas.', 'EE', 5, 40);